#!/usr/bin/env python3
"""p35 (2026-11-02): (1) only real photos: illustrations/renders leave photo selection (merged with the aerial check, one vision question);
(2) agency flag logo_hidden -> no logo on the video. Idempotent, asserts on every anchor, writes .bak_p35. Run from the repo root."""
import os, shutil, sys
BLK1 = '# 2026-11-02 (Michele): only REAL photos go in the video, and no aerial view unless the agency says it shows the property.\n#   - job 4c34217d: a drone / aerial photo labelled "exterior" became the opening scene and the video model invented a street-level zoom; aerial views\n#     also often show a local landmark (Teatro Marcello) instead of the property.\n#   - job 50472245 (GIAL 1272, new building): scenes 0 and 1 were ILLUSTRATIONS / renders; animated they turned into cartoons, and scene 0 hallucinated.\n# ONE question per photo (one extra Claude call): photo | aerial | illustration.\n_VISION_SOURCE_PROMPT = (\n    "Look at this real estate image. What kind of picture is it?\\n"\n    "- photo: a real photograph taken by a person on the ground, inside, on a balcony or at a window.\\n"\n    "- aerial: a real photograph taken FROM THE AIR (drone or aerial view looking down on roofs, streets or land from high above), a satellite image or a map.\\n"\n    "- illustration: a drawing, an architectural render, a CGI image, a 3D visualisation or a sketch (even if it looks realistic, with perfect colours, "\n    "people drawn as silhouettes or a computer-generated sky and plants).\\n"\n    "Answer with ONLY one word: photo, aerial or illustration."\n)\nAERIAL_PROPERTY_CAPTION_WORDS = ("facciata", "prospetto", "immobile", "la proprieta", "la proprietà", "l\'edificio", "palazzina", "villa", "la casa")\nMAX_SOURCE_CHECK = 30\n\n\ndef aerial_filter_enabled() -> bool:\n    """PVS_AERIAL_FILTER=0 turns the aerial / illustration exclusion off (default on)."""\n    return os.getenv("PVS_AERIAL_FILTER", "1").strip().lower() not in ("0", "false", "no", "off")\n\n\ndef _photo_source(image_url: str, fallback_url: str = None) -> tuple:\n    """(word, ok): word is photo | aerial | illustration (anything else counts as photo). ok False = the call failed, callers keep the photo."""\n    word, ok = _vision_one_word(image_url, fallback_url, _VISION_SOURCE_PROMPT)\n    return (word if word in ("photo", "aerial", "illustration") else "photo"), ok\n\n\ndef caption_ties_to_property(label: str) -> bool:\n    low = str(label or "").lower()\n    return any(w in low for w in AERIAL_PROPERTY_CAPTION_WORDS)\n\n\n'
BLK2 = '    # 2026-11-02: only real photos: illustrations / renders leave the selection (any category); aerial views leave it too unless the agency caption ties\n    # them to the property (see _VISION_SOURCE_PROMPT). A failed call keeps the photo.\n    src_check = [p for p in photos if p.get("category") in CATEGORIES and p.get("url")][:MAX_SOURCE_CHECK] if aerial_filter_enabled() else []\n    with ThreadPoolExecutor(max_workers=CLASSIFY_WORKERS) as ex:\n        src_results = list(ex.map(lambda p: _photo_source(p["url"], p.get("original_url")), src_check))\n    aerials = illustrations = 0\n    for p, (word, ok) in zip(src_check, src_results):\n        if not ok:\n            continue\n        if word == "illustration":\n            p["category_before_source"] = p.get("category"); p["category"] = "uncategorized"; p["category_source"] = "vision_illustration"; illustrations += 1\n        elif word == "aerial" and p.get("category") in ("exterior", "outdoor") and not caption_ties_to_property(p.get("label_it")):\n            p["category_before_source"] = p.get("category"); p["category"] = "uncategorized"; p["category_source"] = "vision_aerial"; aerials += 1\n'
FN = 'def set_agency_logo_hidden(agency_id, hidden=True):\n    """2026-11-02: hides (or restores) the agency logo on its future video assemblies without touching the logo file or its path."""\n    agencies = list_agencies()\n    for a in agencies:\n        if a["agency_id"] == agency_id:\n            a["logo_hidden"] = bool(hidden)\n    _save(AGENCIES_FILE, agencies)\n    return get_agency(agency_id)\n\n\n# ── Properties ────────────────────────────────────────────────────────\n# Shared entity with the media library, same pattern as Agencies above\n# (2026-07-22, backlog item 39). One property can have multiple\n# independent jobs over time -- an original video plus a completely\n# separate reshoot months later, not just in-place reworks of the same\n# job (which already don\'t need a new job entry at all -- see the\n# single-directory job model). A property\'s agency_id is its\n# CURRENT/default client; an individual JOB\'s own agency_id can differ\n# if that specific job was actually commissioned by a different agency\n# (e.g. the property gets re-listed with a new agent) -- job_financials()\n# always uses the job\'s own agency_id, never the property\'s, so this\n# stays accurate even when they diverge.\n'
def edit(path, fn):
    s = open(path).read(); shutil.copy(path, path + ".bak_p35"); s = fn(s); open(path, "w").write(s); print("patched", path)
def ls(s):
    if "_VISION_SOURCE_PROMPT" in s: print("listing_scraper already patched"); return s
    a = s.index("# 2026-11-02 (Michele, job 4c34217d): a drone / aerial photo"); b = s.index("def classify_uncategorized_photo(")
    s = s[:a] + BLK1 + s[b:]
    a = s.index("    # 2026-11-02: aerial / drone photos leave the selection"); b = s.index('    # 2026-10-27: photos labelled "living" are checked')
    s = s[:a] + BLK2 + s[b:]
    old = '"aerial_removed": aerials}'; assert old in s; return s.replace(old, '"aerial_removed": aerials, "illustrations_removed": illustrations}')
def cm(s):
    if "def set_agency_logo_hidden" in s: return s
    anchor = "    _save(AGENCIES_FILE, agencies)\n    return get_agency(agency_id)\n\n\n"
    assert s.count(anchor) >= 1
    i = s.rindex("def ", 0, s.index(anchor)); j = s.index(anchor, i) + len(anchor)
    return s[:j] + FN.rstrip() + "\n\n\n" + s[j:]
def api(s):
    old = 'if _agency and _agency.get("logo_path") and os.path.exists(_agency["logo_path"]):'
    if "logo_hidden" in s: print("api_server already patched"); return s
    assert s.count(old) == 1, s.count(old)
    return s.replace(old, '# 2026-11-02: agency flag logo_hidden = no logo on the video (file stays)\n            if _agency and _agency.get("logo_path") and not _agency.get("logo_hidden") and os.path.exists(_agency["logo_path"]):')
for p, f in (("listing_scraper.py", ls), ("cost_model.py", cm), ("api_server.py", api)): edit(p, f)
